import{Z as t,e,f as a,a0 as i}from"./chunks/framework.DmpHOl9T.js";const g=JSON.parse('{"title":"Form Groups and Defaults at Scale","description":"","frontmatter":{},"headers":[],"relativePath":"guides/control-panel-admin/form-groups-and-defaults-at-scale.md","filePath":"guides/control-panel-admin/form-groups-and-defaults-at-scale.md","lastUpdated":1782532814000}'),o={name:"guides/control-panel-admin/form-groups-and-defaults-at-scale.md"};function r(n,s,l,p,h,d){return e(),a("div",null,[...s[0]||(s[0]=[i(`<h1 id="form-groups-and-defaults-at-scale" tabindex="-1">Form Groups and Defaults at Scale <a class="header-anchor" href="#form-groups-and-defaults-at-scale" aria-label="Permalink to &quot;Form Groups and Defaults at Scale&quot;">​</a></h1><p>When a project grows past a handful of forms, the control panel gets noisy and new forms drift from your standards. Form groups organise the forms index, enforce policies, and layer group-level defaults on top of global Formie settings — without changing how forms render on the front end.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li><a href="/forms/form-groups">Form Groups</a></li><li><a href="/get-started/configuration">Configuration</a> — global defaults in <code>config/formie.php</code> and <strong>Settings → Defaults</strong></li></ul><h2 id="when-to-use-groups" tabindex="-1">When to Use Groups <a class="header-anchor" href="#when-to-use-groups" aria-label="Permalink to &quot;When to Use Groups&quot;">​</a></h2><p>Form groups help when:</p><ul><li>Several teams each own a set of forms</li><li>You want sidebar filters instead of one long forms list</li><li>New forms should land in a known bucket with consistent defaults</li></ul><p>If you only have a few forms, skip groups — <strong>All forms</strong> works fine.</p><p>Groups do <strong>not</strong> change front-end rendering, templates, or existing submission behaviour until you change form settings.</p><h2 id="step-1-—-plan-your-group-structure" tabindex="-1">Step 1 — Plan Your Group Structure <a class="header-anchor" href="#step-1-—-plan-your-group-structure" aria-label="Permalink to &quot;Step 1 — Plan Your Group Structure&quot;">​</a></h2><p>A typical agency or enterprise layout:</p><table tabindex="0"><thead><tr><th>Group</th><th>Purpose</th><th>Site policy</th></tr></thead><tbody><tr><td>Marketing</td><td>Lead gen, newsletters</td><td>All sites or regional subset</td></tr><tr><td>Support</td><td>Tickets, feedback</td><td>Internal site only</td></tr><tr><td>HR</td><td>Applications, onboarding</td><td>Created-site-only propagation</td></tr></tbody></table><p>Create groups under <strong>Formie → Settings → Form Groups</strong>. Each group has a name, handle, and sort order. Definitions live in <a href="/get-started/configuration#form-groups-project-config">project config</a> and travel with the repo.</p><h2 id="step-2-—-configure-site-policy-multi-site" tabindex="-1">Step 2 — Configure Site Policy (Multi-Site) <a class="header-anchor" href="#step-2-—-configure-site-policy-multi-site" aria-label="Permalink to &quot;Step 2 — Configure Site Policy (Multi-Site)&quot;">​</a></h2><p>On multi-site Craft installs, each group restricts <strong>which sites</strong> forms may exist on and how new forms <strong>propagate</strong>.</p><p>Under <strong>General → Site Policy</strong>:</p><ul><li><strong>Enabled Sites</strong> — tick only the sites forms in this group may use</li><li><strong>Site Propagation</strong> — control how new forms spread (all enabled sites, created site only, same language, same site group)</li></ul><p>Example: an <strong>Australia Forms</strong> group with only the Australia site enabled, propagation set to <strong>All enabled sites</strong>. Forms in that group never appear on Global or New Zealand sites.</p><p>See <a href="/guides/control-panel-admin/translating-forms-across-craft-sites">Translating forms across Craft sites</a> for how availability differs from translation.</p><h2 id="step-3-—-set-group-defaults" tabindex="-1">Step 3 — Set Group Defaults <a class="header-anchor" href="#step-3-—-set-group-defaults" aria-label="Permalink to &quot;Step 3 — Set Group Defaults&quot;">​</a></h2><p>Blank group settings inherit from global <strong>Formie → Settings → Defaults</strong>. Override only what the group needs:</p><table tabindex="0"><thead><tr><th>Tab</th><th>Example override</th></tr></thead><tbody><tr><td><strong>Form Defaults</strong></td><td><code>collectIp: true</code>, <code>submitMethod: ajax</code>, default submission status</td></tr><tr><td><strong>Field Defaults</strong></td><td>File Upload volume, Date display type</td></tr><tr><td><strong>Validation Messages</strong></td><td>Plugin-wide validation copy for this team&#39;s forms</td></tr><tr><td><strong>Notification Defaults</strong></td><td>From address, Reply-To, attach PDF default</td></tr><tr><td><strong>Integration Defaults</strong></td><td>Captcha enabled/disabled for new forms</td></tr></tbody></table><p>New forms created in the group pick up these defaults. Existing forms are unchanged until you edit them.</p><h3 id="submission-limits-vs-groups" tabindex="-1">Submission Limits vs Groups <a class="header-anchor" href="#submission-limits-vs-groups" aria-label="Permalink to &quot;Submission Limits vs Groups&quot;">​</a></h3><p><a href="/forms/submission-limits">Submission limits</a> are <strong>per form</strong>, not per group. If your group often uses per-user or per-IP limits, preset <strong>Collect User</strong> or <strong>Collect IP</strong> on the group <strong>Form Defaults</strong> tab so new forms inherit the privacy settings those limits need.</p><p>Global abuse throttling lives under <strong>Settings → Spam Protection</strong> — separate from form submission limits.</p><h2 id="step-4-—-custom-field-palette" tabindex="-1">Step 4 — Custom Field Palette <a class="header-anchor" href="#step-4-—-custom-field-palette" aria-label="Permalink to &quot;Step 4 — Custom Field Palette&quot;">​</a></h2><p>Enable <strong>Use custom field palette</strong> on the <strong>Field Palette</strong> tab when a team should only see a subset of field types — for example, no Payment or Repeater for marketing self-service authors.</p><p>When disabled, the group inherits the global palette from <strong>Settings → Fields</strong>.</p><h2 id="step-5-—-allowed-submission-statuses" tabindex="-1">Step 5 — Allowed Submission Statuses <a class="header-anchor" href="#step-5-—-allowed-submission-statuses" aria-label="Permalink to &quot;Step 5 — Allowed Submission Statuses&quot;">​</a></h2><p>Restrict which submission statuses forms in the group may use. Choose <strong>All</strong> to allow every status, or pick a subset for workflow consistency (for example, Support forms may only use <strong>New</strong>, <strong>In progress</strong>, <strong>Closed</strong>).</p><p>This policy applies to all forms in the group; individual forms cannot override it.</p><h2 id="step-6-—-work-in-the-forms-index" tabindex="-1">Step 6 — Work in the Forms Index <a class="header-anchor" href="#step-6-—-work-in-the-forms-index" aria-label="Permalink to &quot;Step 6 — Work in the Forms Index&quot;">​</a></h2><p>When at least one group exists, the sidebar shows:</p><ul><li><strong>All forms</strong></li><li><strong>Groups</strong> — one source per group</li><li><strong>Ungrouped</strong> — forms with no group</li></ul><p>Creating a form from a group source pre-assigns that group. Use <strong>Move to group</strong> bulk actions to reorganise later.</p><p>The submissions index groups forms under the same headings when groups exist.</p><h2 id="step-7-—-layer-config-file-defaults" tabindex="-1">Step 7 — Layer Config File Defaults <a class="header-anchor" href="#step-7-—-layer-config-file-defaults" aria-label="Permalink to &quot;Step 7 — Layer Config File Defaults&quot;">​</a></h2><p>For developer-controlled defaults that apply before the control panel, use <code>config/formie.php</code>:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;*&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &#39;defaultFormStencil&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;contactForm&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &#39;formDefaults&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">            &#39;collectIp&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">            &#39;submitMethod&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;ajax&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        ],</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &#39;notificationDefaults&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">            &#39;from&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;notifications@example.com&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        ],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span></code></pre></div><p>Precedence in practice:</p><ol><li><strong>Global config</strong> (<code>formie.php</code>) — baseline for all environments</li><li><strong>Global CP defaults</strong> — <strong>Settings → Defaults</strong></li><li><strong>Group defaults</strong> — override global where set</li><li><strong>Individual form</strong> — final authority once saved</li></ol><p>Document which layer owns which setting so editors know where to look.</p><h2 id="step-8-—-combine-with-stencils" tabindex="-1">Step 8 — Combine with Stencils <a class="header-anchor" href="#step-8-—-combine-with-stencils" aria-label="Permalink to &quot;Step 8 — Combine with Stencils&quot;">​</a></h2><p>Groups organise <em>where</em> forms live; <a href="/forms/stencils">stencils</a> define <em>what</em> new forms start with. Set <code>defaultFormStencil</code> globally or train authors to pick a stencil when creating forms in each group.</p><p>See <a href="/guides/control-panel-admin/stencils-for-repeatable-form-types">Stencils for repeatable form types</a>.</p>`,46)])])}const f=t(o,[["render",r]]);export{g as __pageData,f as default};
